.vc-premium-footer__grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  padding: clamp(2rem, 3.8vw, 4rem);
  align-items: start;
}
.vc-premium-footer__navcols {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
