}
.vc-premium-footer__logo {
  display: flex;
  width: 2rem;
  height: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  overflow: hidden;
  /* footerBrandVinyl1: icona server/vinile (no foglia, no caffè) */
  background: #140f0c;
  box-shadow: inset 0 0 0 1px rgba(245, 214, 183, 0.28);
}
.vc-premium-footer__logo-img,
.vc-premium-footer__logo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
}
.vc-premium-footer__wordmark {
  color: #ead6bb;
  font-size: clamp(1.25rem, 4vw, 1.625rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0;
}
.vc-premium-footer__desc {
  margin: 0;
  max-width: min(28rem, 100%);
  width: 100%;
  color: rgba(234, 214, 187, 0.78) !important;
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1.55;
  text-align: left !important;
  align-self: stretch;
}
.vc-premium-footer__socials {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.vc-premium-footer__social {
  display: flex;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.18);
  border-radius: 0.75rem;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.025));
