.discord-account-popover {
  position: absolute;
  right: -0.2rem;
  top: calc(100% + 0.75rem);
  z-index: 70;
  width: 16.5rem;
  padding: 0.55rem;
  border-radius: 1.2rem;
  border: 1px solid rgba(var(--vc-sand-rgb), 0.28);
  background: #100c09;
  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.48),
    0 0 18px rgba(var(--vc-sand-rgb), 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-4px);
  transition:
    opacity 0.18s ease,
    visibility 0.18s ease,
    transform 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}
.discord-account-popover::before {
  content: "";
  position: absolute;
  right: 1.65rem;
  top: -0.42rem;
  width: 0.8rem;
  height: 0.8rem;
  transform: rotate(45deg);
  border-left: 1px solid rgba(var(--vc-sand-rgb), 0.28);
  border-top: 1px solid rgba(var(--vc-sand-rgb), 0.28);
  background: #100c09;
}
/* acctTriggerOnly1: no menu:hover open (ghost Dashboard/Bacheca/Esci) */
.discord-account-menu > .discord-account-popover {
  display: none;
}
.discord-account-menu:has(> .discord-profile-link:hover) > .discord-account-popover,
.discord-account-menu:has(> .discord-profile-link:focus-visible) > .discord-account-popover,
.discord-account-menu:focus-within > .discord-account-popover,
html.vc-header-account-open:not(.vc-notif-dropdown-open) .discord-account-menu > .discord-account-popover {
  display: block;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

