.vc-mobile-nav-drawer {
  position: fixed;
  inset: 0;
  z-index: 10050;
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  transition:
    opacity 0.22s ease,
    visibility 0.22s ease;
}
.vc-mobile-nav-drawer--open {
  pointer-events: auto;
  visibility: visible;
  opacity: 1;
}
.vc-mobile-nav-drawer__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 6, 23, 0.52);
  backdrop-filter: blur(var(--vc-glass-blur-strong)) saturate(160%);
  -webkit-backdrop-filter: blur(var(--vc-glass-blur-strong)) saturate(160%);
}
.vc-mobile-nav-drawer__panel {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  max-width: 100%;
  background: linear-gradient(168deg, #0f0c12 0%, #15101c 42%, #0b0a10 100%);
  border-left: 1px solid rgba(212, 168, 136, 0.12);
  transform: translateX(104%);
  transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1);
}
.vc-mobile-nav-drawer--open .vc-mobile-nav-drawer__panel {
  transform: translateX(0);
}
.vc-mobile-nav-drawer__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  flex-shrink: 0;
  min-height: 3.65rem;
}
.vc-mobile-nav-drawer__brand {
  display: flex;
  align-items: center;
  align-self: center;
  gap: 0.65rem;
  min-width: 0;
  flex: 1;
  min-height: 2.5rem;
}
.vc-mobile-nav-drawer__brand a.vc-header-logo-link {
  flex-shrink: 0;
  align-self: center;
  display: inline-flex;
  align-items: center;
}
.vc-mobile-nav-drawer__top-actions {
  display: flex;
  align-items: center;
  align-self: center;
  gap: 0.35rem;
  flex-shrink: 0;
  min-height: 2.5rem;
}
.vc-mobile-nav-drawer__close {
  display: inline-flex;
  width: 2.5rem;
  height: 2.5rem;
  padding: 0;
  border-radius: 0.65rem;
  border: 1px solid rgba(248, 113, 113, 0.72);
  background: rgba(185, 28, 28, 0.5);
  color: #fecaca;
  align-items: center;
  justify-content: center;
  cursor: var(--vc-cursor-pointer);
  box-shadow: inset 0 0 0 1px rgba(127, 29, 29, 0.35);
}
.vc-mobile-nav-drawer__close:hover {
  border-color: rgba(252, 165, 165, 0.9);
  background: rgba(220, 38, 38, 0.62);
  color: #fff;
}
.vc-mobile-nav-drawer__scroll {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 1rem 1rem 0.75rem;
  -webkit-overflow-scrolling: touch;
}
/* mobileNavBtn2: categorie apri/chiudi (details) + tile bottone */
.vc-mobile-nav-section {
  margin: 0.85rem 0 0;
  border: 0;
}
.vc-mobile-nav-section:first-child {
  margin-top: 0;
}
.vc-mobile-nav-section-title {
  margin: 0 0 0.5rem;
  font-family: "Inter", ui-sans-serif, system-ui, sans-serif;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: rgba(247, 236, 223, 0.55);
  text-transform: uppercase;
}
details.vc-mobile-nav-section > summary.vc-mobile-nav-section-title {
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem;
  margin: 0 0 0.55rem;
  padding: 0.4rem 0.2rem;
  cursor: var(--vc-cursor-pointer, pointer);
  user-select: none;
  -webkit-user-select: none;
  color: rgba(247, 236, 223, 0.72);
}
details.vc-mobile-nav-section > summary.vc-mobile-nav-section-title::-webkit-details-marker {
  display: none;
}
details.vc-mobile-nav-section > summary.vc-mobile-nav-section-title .vc-mobile-nav-section-title__txt {
  min-width: 0;
}
details.vc-mobile-nav-section > summary.vc-mobile-nav-section-title .vc-mobile-nav-section-chev {
  flex: 0 0 auto;
  font-size: 0.85rem;
  color: rgba(247, 236, 223, 0.55);
  transition: transform 0.16s ease;
}
